const body = $json.body ?? $json;
const factores = Array.isArray(body.factores) ? body.factores : [];
const prompt = [
  'Eres analista de entorno externo para una empresa en Colombia.',
  'Con los factores PESTEL aprobados redacta un informe en español, en markdown.',
  'No inventes factores que no estén en los datos. Si falta información, dilo.',
  '',
  'Estructura obligatoria:',
  '## Resumen ejecutivo',
  '## Análisis PESTEL',
  'Una subsección por cada categoría que tenga factores (Político, Económico, Social, Tecnológico, Ecológico, Legal).',
  '## Prioridades',
  'Agrupa por nivel CRÍTICO, ATENCIÓN y MONITOREAR.',
  '## Hoja de ruta',
  'Acciones a corto, mediano y largo plazo. Cada acción indica el factor que la origina y el resultado esperado.',
  '',
  'Empresa: ' + (body.empresa ?? 'Sin nombre'),
  'NIT: ' + (body.nit ?? 'Sin NIT'),
  'Sector: ' + (body.sectorNombre ?? body.sector ?? 'Sin sector'),
  'Ciudad: ' + (body.ciudad ?? 'Sin ciudad'),
  '',
  'Factores aprobados:',
  JSON.stringify(factores, null, 2),
].join('\n');

return [{
  json: {
    geminiBody: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: { temperature: 0.4, maxOutputTokens: 8192 },
    },
  },
}];

const parts = $json.candidates?.[0]?.content?.parts ?? [];
const texto = parts.map((parte) => parte.text ?? '').join('\n').trim();
if (!texto) {
  throw new Error('Gemini no devolvió texto');
}
return [{ json: { texto } }];
